/**
 * The farm's own fifteen posts, lifted out of its WordPress install and
 * re-encoded for this site. Titles, dates, categories, words and photographs
 * are all theirs; nothing here is written for the page.
 *
 * Two mechanical editorial passes, both worth knowing about:
 *  - WordPress files most posts under three or four overlapping categories at
 *    once (Bourbon, Distillery, Flying Ace Farm News, Uncategorized). The index
 *    needs exactly one to filter by, so each post carries the most specific of
 *    them as its `section`.
 *  - The stored excerpts are WordPress auto-excerpts, cut at 55 words wherever
 *    that lands. Several opened mid-sentence and one opened on a bare heading,
 *    so each `excerpt` here is the post's own first paragraph, cut at a full
 *    stop.
 *
 * The data and the images are the committed output of a one-off extraction, so
 * nothing on this site calls WordPress at run time or at build time.
 */

export type Section = 'Distillery' | 'Brewery' | 'Events';

/** One piece of a post's body. `html` carries only a, strong, em and br. */
export type Block =
  | { t: 'h2' | 'h3' | 'p'; html: string }
  | { t: 'ul'; items: string[] }
  | { t: 'img'; src: string; w: number; h: number; alt: string }
  | { t: 'rule' };

export type Post = {
  slug: string;
  title: string;
  /** ISO. Parsed as UTC below, so the printed date never shifts with the build machine. */
  date: string;
  section: Section;
  tags: string[];
  excerpt: string;
  card: { src: string; w: number; h: number };
  hero: { src: string; w: number; h: number };
  body: Block[];
};

