/* The filter on the index, in the order the farm writes about them. */
export const sections: Section[] = ['Distillery', 'Brewery', 'Events'];

const MONTHS = [
  'January',
  'February',
  'March',
  'April',
  'May',
  'June',
  'July',
  'August',
  'September',
  'October',
  'November',
  'December',
];

/** Parsed as UTC, so the printed date never shifts with the build machine's zone. */
export const readable = (iso: string): string => {
  const [y, m, d] = iso.split('-').map(Number);
  return `${MONTHS[m - 1]} ${d}, ${y}`;
};

